try:
    import numpy as np
except Exception:
    np = None


class GuardError(RuntimeError):
    """Invariant failure: stop, do not accept any trial."""


class MarginalGuardError(GuardError):
    """Total or the evidence-based constrained marginal failed; reject and restore."""


class MarginalCalibrationHalt(GuardError):
    """All bounded retries failed genuine invariant checks; preserve accepted state."""


class ExecutionError(GuardError):
    """Native execution failed/no output; not an optimization plateau."""


class StopRequested(Exception):
    pass


def require(ok, message):
    if not ok:
        raise GuardError(message)


def timestamp():
    return datetime.now().astimezone().isoformat(timespec="seconds")


def number(value):
    if isinstance(value, str):
        value = value.replace("\xa0", "").replace(" ", "").replace(",", ".")
    value = float(value)
    require(math.isfinite(value), "Non-finite numeric value")
    return value


def sha_array(array):
    return hashlib.sha256(np.ascontiguousarray(array, dtype="<f8").tobytes()).hexdigest()


def sha_file(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for chunk in iter(lambda: f.read(4 * 1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def verify_2022_osrm_amdy_patched_inputs(protected, zone_order, report_path=None):
    """Fail closed if calibration would use the old unpatched .ver.

    Every one of the 3402 distinct amended M9001/M9697 input cells must
    match the approved OSRM/AMDY authority. Only protected inputs are read;
    this function does not invoke Visum procedures or write model matrices.
    The tolerance allows insignificant numerical rounding on .ver reload.
    """
    require(np is not None, "NumPy required for input verification")
    require(len(zone_order) == 681 and set(zone_order) == set(range(1,682)),
            "Patched R1 requires exactly 681 unique zone IDs")
    require(9001 in protected and 9697 in protected, "M9001/M9697 not available")
    raw = zlib.decompress(base64.b64decode(PATCH_2022_EXPECTED_CELLS_B64))
    digest = hashlib.sha256(raw).hexdigest()
    require(digest == PATCH_2022_EXPECTED_DECODED_SHA256,
            "Embedded approved OSRM/AMDY cell authority checksum mismatch")
    policy = json.loads(raw.decode("ascii"))
    cells = policy["target_cells"]
    require(len(cells) == 3402 and len({(v[0],v[1],v[2]) for v in cells}) == 3402,
            "Invalid 3402-cell input authority")
    pos = {int(z): i for i,z in enumerate(zone_order)}
    tolerance = float(CONFIG["patched_input_abs_tolerance"])
    errors = []
    max_abs_error = 0.0
    counts = {9001:0, 9697:0}
    for no, origin, dest, want in cells:
        a = protected[int(no)]
        got = float(a[pos[int(origin)],pos[int(dest)]])
        diff = abs(got-float(want))
        max_abs_error=max(max_abs_error,diff)
        counts[int(no)] += 1
        if not math.isfinite(got) or diff > tolerance:
            if len(errors)<20:
                errors.append({"matrix_no":no,"from_zone":origin,"to_zone":dest,
                               "expected":want,"actual":got,"absolute_difference":diff})
    require(counts == {9001:1361,9697:2041}, "Unexpected patched input target counts")
    diag={}
    min_offdiag={}
    for no in (9001,9697):
        a=np.asarray(protected[no],dtype=np.float64)
        require(a.shape==(681,681) and np.isfinite(a).all(), "Invalid input matrix M%d"%no)
        d=np.diag(a)
        diag[no] = float(d.min())
        offdiag=a[~np.eye(681,dtype=bool)]
        min_offdiag[no]=float(offdiag.min())
    status=(not errors and min(diag.values())>0 and min(min_offdiag.values())>0)
    report={"schema":"R1_2022_PATCHED_INPUT_PREFLIGHT_V1", "status":
            "VERIFIED_PATCHED_AMDY_OSRM_INPUTS" if status else "REJECTED_WRONG_OR_UNPATCHED_MODEL",
            "authority_decoded_sha256":digest, "source_hashes":policy["source_hashes"],
            "target_cells_checked":len(cells),"target_counts_by_matrix":counts,
            "max_abs_target_cell_error":max_abs_error,
            "allowed_abs_cell_error":tolerance,
            "minimum_diagonal_by_matrix":diag,
            "minimum_offdiagonal_by_matrix":min_offdiag,
            "example_mismatches":errors,
            "note":"Checked patched input data only; existing OD matrices are stale and will be regenerated by native TD."}
    if report_path is not None:
        write_json(report_path,report)
    require(status, "Patched OSRM/AMDY inputs not verified. Open OSRM_AMDY_INPUTS_PATCHED_TD_STALE.ver; see 02_PATCHED_INPUT_PREFLIGHT.json")
    return report


def plain(value):
    if isinstance(value, dict):
        return {str(k): plain(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [plain(v) for v in value]
    if np is not None and isinstance(value, np.ndarray):
        return value.tolist()
    if np is not None and isinstance(value, np.generic):
        return value.item()
    return value


def default_output_root():
    """Keep frequently overwritten progress/NPZ/VER files away from OneDrive.

    LOCALAPPDATA points to the Windows *local* profile, not OneDrive. A caller
    can still provide an explicit output_root to main() for controlled tests.
    """
    base = os.environ.get("LOCALAPPDATA", "").strip()
    return (Path(base) if base else Path(tempfile.gettempdir())) / ROOT_NAME


def replace_with_retry(temp, path):
    """Commit one complete file atomically, retrying Windows transient locks.

    Permanent permission failures are NOT swallowed: failing safely is better
    than pretending evidence was recorded when it was not. The .tmp payload
    survives until the rename succeeds so the previous committed file is intact.
    """
    last_error = None
    for attempt in range(CONFIG["atomic_replace_retry_count"]):
        try:
            os.replace(str(temp), str(path))
            return
        except OSError as exc:
            transient = (getattr(exc, "winerror", None) in (5, 32, 33)
                         or getattr(exc, "errno", None) in (errno.EACCES, errno.EPERM, errno.EBUSY))
            if not transient or attempt == CONFIG["atomic_replace_retry_count"]-1:
                raise
            last_error = exc
            time.sleep(min(0.05 * (2 ** attempt), 1.0))
    raise last_error  # pragma: no cover; loop always raises or returns


def preflight_output_storage(root):
    """Detect lack of write/replace permissions before touching Visum's model."""
    temp = root / "00_STORAGE_PREFLIGHT.txt.tmp"
    final = root / "00_STORAGE_PREFLIGHT.txt"
    with temp.open("w", encoding="ascii") as f:
        f.write("R1_BC_LOCAL_OUTPUT_READWRITE_OK\n")
        f.flush()
        os.fsync(f.fileno())
    replace_with_retry(temp, final)
    require(final.read_text(encoding="ascii").strip() == "R1_BC_LOCAL_OUTPUT_READWRITE_OK",
            "Cannot verify write/read round-trip in output folder")
    final.unlink()


def write_json(path, data):
    path = Path(path)
    temp = path.with_name(path.name + ".tmp")
    with temp.open("w", encoding="utf-8") as f:
        json.dump(plain(data), f, ensure_ascii=True, indent=2, allow_nan=False)
        f.flush()
        os.fsync(f.fileno())
    replace_with_retry(temp, path)


def write_csv(path, rows):
    rows = [plain(r) for r in rows]
    fields = list(dict.fromkeys(k for r in rows for k in r)) or ["empty"]
    path = Path(path)
    temp = path.with_name(path.name + ".tmp")
    with temp.open("w", newline="", encoding="utf-8-sig") as f:
        w = csv.DictWriter(f, fieldnames=fields, delimiter=";", extrasaction="ignore")
        w.writeheader()
        w.writerows(rows)
    replace_with_retry(temp, path)


def dump_arrays(path, arrays):
    path = Path(path)
    temp = path.with_name(path.name + ".tmp")
    with temp.open("wb") as f:
        np.savez_compressed(f, **{"M%d" % n: a for n, a in arrays.items()})
        f.flush()
        os.fsync(f.fileno())
    replace_with_retry(temp, path)


def get_all(collection):
    raw = collection.GetAll
    return list(raw() if callable(raw) else raw)


def safe_att(obj, name):
    try:
        value = obj.AttValue(name)
        return str(value) if value is not None else ""
    except Exception:
        return ""


def live_visum():
    # Deliberately NO GetActiveObject fallback: multiple open windows are ambiguous.
    for key in ("Visum", "COM"):
        value = globals().get(key)
        if value is not None and hasattr(value, "Net") and hasattr(value, "Procedures"):
            return value
    raise GuardError("Run through Visum > Scripts > Execute script file. No injected Visum/COM object.")


class Log:
    def __init__(self, root):
        self.root = Path(root)
        self.phase = "START"
        self.started = time.monotonic()
        self.history = []
        self.warnings = []
        self.summary = {"script_id": SCRIPT_ID, "status": "RUNNING", "started": timestamp(),
                        "config": CONFIG, "result_dir": str(root), "warnings": self.warnings,
                        "scope": "DIST_ONLY; P/A and network frozen; native TD only",
                        "marginal_policy": "native constraint-aware, per-matrix inferred side; other side diagnostic only"}
        self.event("START", "Automatic DIST-only calibration")

    def event(self, phase, text):
        self.phase = phase
        line = "%s | %s | %s" % (timestamp(), phase, text)
        with (self.root / "00_STATUS.txt").open("a", encoding="utf-8") as f:
            f.write(line + "\n")
            f.flush()
        # NO print: Visum displays Python stdout as modal Information windows.
        # 00_STATUS.txt is the sole progress channel.
        self.summary["last_phase"] = phase
        self.summary["updated"] = timestamp()
        write_json(self.root / "00_MASTER_SUMMARY.json", self.summary)

    def check_stop(self, evaluations):
        if (self.root / "STOP.txt").exists() or (self.root.parent.parent / "STOP_R1_BC.txt").exists():
            raise StopRequested("USER_STOP_FILE")
        if time.monotonic() - self.started >= CONFIG["max_runtime_seconds"]:
            raise StopRequested("TIME_BUDGET")
        if evaluations >= CONFIG["max_td_evaluations"]:
            raise StopRequested("TD_EVALUATION_BUDGET")


class SilentProcedureWarnings:
    """Enable native Visum warning suppression; restore exact GUI preferences.

    Uses the documented IGUIUserPreferences attribute
    SuppressWarningsDuringProcExec. No Windows SendKeys or unconditional
    acknowledgement of dialogs is used. Error dialogs are intentionally not
    suppressed by this preference and must be treated as failures.
    """

    WARNING_ATTR = "SuppressWarningsDuringProcExec"
    LOG_ATTR = "SaveWarningsToErrorFile"
    GUI_NAMES = (
        "GUI", "Gui", "GUIUserPreferences", "GuiUserPreferences",
        "UserInterface", "UI", "GUIOptions", "GuiOptions", "General",
    )

    def __init__(self, visum, log):
        self.visum = visum
        self.log = log
        self.changes = []
        self.native_message_old = None
        self.native_message_new = None
        self.enabled = False

    def candidates(self):
        # Some Visum builds expose IGUIUserPreferences directly; others use
        # UserPreferences.GUI. Only a verified AttValue read is accepted.
        containers = []
        try:
            containers.append(("UserPreferences", self.visum.UserPreferences))
        except Exception as exc:
            self.log.warnings.append("UserPreferences unavailable: %r" % exc)
        for prefix, obj in containers:
            for name in self.GUI_NAMES:
                try:
                    sub = getattr(obj, name)
                    if callable(sub):
                        sub = sub()
                    if sub is not None:
                        yield (prefix + "." + name, sub)
                except Exception:
                    continue
            yield (prefix, obj)

    @staticmethod
    def get_flag(obj, attr):
        v = obj.AttValue(attr)
        if v is None or str(v).strip() == "":
            raise ValueError("empty preference value: " + attr)
        if isinstance(v, str) and v.lower() in ("true", "false"):
            return int(v.lower() == "true")
        return int(float(str(v).strip().replace(",", ".")) != 0)

    def set_verified(self, obj, attr, value):
        old = self.get_flag(obj, attr)
        if old != int(value):
            obj.SetAttValue(attr, int(value))
            self.changes.append((obj, attr, old))
        after = self.get_flag(obj, attr)
        if after != int(value):
            raise GuardError("Native warning preference readback failed: %s (got %s)" % (attr, after))
        return old

    def enable(self):
        errors = []
        for path, gui in self.candidates():
            try:
                # First read-only check. Do not write to a guessed COM object.
                original = self.get_flag(gui, self.WARNING_ATTR)
            except Exception as exc:
                errors.append("%s: %s" % (path, str(exc)[:150]))
                continue
            self.set_verified(gui, self.WARNING_ATTR, 1)
            self.enabled = True
            self.log.summary["silent_native_warning_preference"] = {
                "status": "VERIFIED", "com_path": path,
                "attribute": self.WARNING_ATTR, "previous": original, "current": 1,
            }
            try:
                self.set_verified(gui, self.LOG_ATTR, 1)
                self.log.summary["save_native_warnings_to_message_file"] = "ENABLED"
            except Exception as exc:
                self.log.warnings.append("Cannot enable warning messages file: %r" % exc)
                self.log.summary["save_native_warnings_to_message_file"] = "NOT_VERIFIED"
            self.log.event("SILENT_NATIVE_WARNINGS_ON", "Verified %s.%s=1; native error dialogs are not auto-clicked" % (path, self.WARNING_ATTR))
            self._redirect_message_file()
            return

        self.log.summary["silent_native_warning_preference"] = {
            "status": "NOT_ACCESSIBLE", "probes": errors[:14]
        }
        if CONFIG["require_verified_silent_warnings"]:
            raise GuardError(
                "Cannot verify Visum 2026 SuppressWarningsDuringProcExec via COM. "
                "Calibration was NOT started. In Visum set Edit > User preferences > "
                "User interface > Warnings > Suppress output of warnings during "
                "procedure execution, or provide 00_MASTER_SUMMARY.json for COM-path repair."
            )
        self.log.warnings.append("Native warnings suppression not verified")

    def _redirect_message_file(self):
        if not CONFIG["capture_native_message_file"]:
            return
        # Save and restore the original filename. Failure of this *optional*
        # capture must not disable already verified native warning suppression.
        try:
            old = str(self.visum.MessageFileName or "")
            if not old:
                self.log.warnings.append("Native message file path empty; retaining Visum's current path")
                return
            new = str(self.log.root / "VISUM_NATIVE_MESSAGES.txt")
            self.visum.SetMessageFileName(new)
            actual = str(self.visum.MessageFileName or "")
            if os.path.normcase(os.path.normpath(actual)) != os.path.normcase(os.path.normpath(new)):
                raise GuardError("Message file readback mismatch")
            self.native_message_old, self.native_message_new = old, new
            self.log.summary["native_message_file_redirected"] = new
            self.log.event("NATIVE_MESSAGES_REDIRECTED", new)
        except Exception as exc:
            self.log.warnings.append("Native message file redirection unavailable: %r" % exc)
            self.log.summary["native_message_file_redirected"] = "NOT_VERIFIED"

    def restore(self):
        errors = []
        # Restore logfile first while the warning capture is still active.
        if self.native_message_old is not None:
            try:
                self.visum.SetMessageFileName(self.native_message_old)
                actual = str(self.visum.MessageFileName or "")
                if os.path.normcase(os.path.normpath(actual)) != os.path.normcase(os.path.normpath(self.native_message_old)):
                    raise GuardError("Original message file not restored")
            except Exception as exc:
                errors.append("message file: %r" % exc)
        for obj, attr, old in reversed(self.changes):
            try:
                obj.SetAttValue(attr, old)
                if self.get_flag(obj, attr) != old:
                    raise GuardError("Preference readback mismatch after restore: " + attr)
            except Exception as exc:
                errors.append("%s: %r" % (attr, exc))
        self.changes[:] = []
        if errors:
            raise GuardError("Could not restore native GUI warning preferences: " + "; ".join(errors))
        if self.enabled:
            self.log.event("SILENT_NATIVE_WARNINGS_RESTORED", "Original Visum user preferences restored")
        self.enabled = False


class VisumAdapter:
    """Thin live adapter; no COM proxies cross a LoadVersion (none is called)."""
    def __init__(self, visum, log):
        self.v = visum
        self.log = log
        self.n = CONFIG["expected_zone_count"]
        self.ops = get_all(self.v.Procedures.Operations)
        self.inventory = []
        candidates = []
        expected = {r["dstrat_code"] for r in COMPONENTS}
        for i, op in enumerate(self.ops, 1):
            typ = int(number(op.AttValue("OPERATIONTYPE")))
            active = bool(number(op.AttValue("ACTIVE")))
            row = {"index": i, "type": typ, "active": int(active),
                   "comment": safe_att(op, "COMMENT"), "is_group": typ == CONFIG["td_group_type"]}
            self.inventory.append(row)
            if typ == 46:
                td = op.TripDistributionParameters
                raw = str(td.AttValue("DSTRATSET"))
                codes = {s.strip() for s in raw.split(",") if s.strip()}
                if codes == expected:
                    candidates.append((i, td, raw))
        write_csv(log.root / "01_PROCEDURE_INVENTORY.csv", self.inventory)
        require(len(candidates) == 1, "Expected exactly one TD operation containing all 17 R1 strata; found %d" % len(candidates))
        self.td_index, self.td, self.original_dset = candidates[0]
        require(self.inventory[self.td_index - 1]["active"], "R1 TD operation is inactive. No execution attempted.")
        # Groups are identified from the verified R1 operation inventory and never switched.
        for r, op in zip(self.inventory, self.ops):
            if r["is_group"]:
                require(op.GroupParameters is not None, "Operation type 75 does not expose GroupParameters")
        self.active_dset = ",".join(r["dstrat_code"] for r in COMPONENTS if r["matrix_no"] != 9116)
        pairs = list(self.v.Net.Zones.GetMultiAttValues("NO"))
        zone_nos = [int(number(v)) for _k, v in pairs]
        # Matrices use the live zone order; do not silently reorder only one input.
        require(len(zone_nos) == self.n and len(set(zone_nos)) == self.n,
                "Invalid zone count/order")
        require(set(zone_nos) == set(range(1, self.n + 1)), "Expected Zone.NO 1..681")
        self.zone_order = zone_nos
        self.controls_changed = False
        self.model_mutated = False
        self.entry_abc = self.read_abc()
        self.zone_guards = self.capture_zone_guards()
        self.protected = {}
        self.optional_protected_missing = []
        for no in [9001, 9697, 9116] + list(range(9301, 9307)) + list(range(9401, 9407)) + [301, 302]:
            try:
                a = self.read_matrix(no)
            except Exception:
                if no in (9001, 9697, 9116):
                    raise
                self.optional_protected_missing.append(no)
                continue
            self.protected[no] = a
        self.protected_hashes = {n: sha_array(a) for n, a in self.protected.items()}
        require(np.min(self.protected[9697]) >= 0, "Negative DIST_KM cells")
        if CONFIG["require_2022_patch_preflight"]:
            patch_report = verify_2022_osrm_amdy_patched_inputs(
                self.protected, self.zone_order, self.log.root / "02_PATCHED_INPUT_PREFLIGHT.json")
            log.summary["patched_2022_inputs_verified"] = True
            log.summary["patched_2022_verified_cells"] = patch_report["target_cells_checked"]
            log.event("PATCHED_INPUTS_VERIFIED", "M9001/M9697: 3402 authorized OSRM/AMDY values verified")
        self.initial_matrices = self.read_outputs()
        self.zero = np.zeros((self.n, self.n), dtype=float)
        write_json(log.root / "02_FROZEN_STATE.json", {
            "zone_order": zone_nos, "zone_attribute_guards": self.zone_guards,
            "protected_matrix_hashes": self.protected_hashes,
            "optional_protected_matrices_not_present": self.optional_protected_missing,
            "initial_output_hashes": {n: sha_array(a) for n, a in self.initial_matrices.items()},
            "original_dstratset": self.original_dset, "calibration_dstratset": self.active_dset,
            "td_index": self.td_index, "abc": self.entry_abc,
        })
        log.event("PREFLIGHT_READ_OK", "TD #%d; 17 ABC; %d zones; native outputs and frozen inputs captured" % (self.td_index, self.n))

    def capture_zone_guards(self):
        attrs = ["ADD_PROD_W", "ADD_ATT_W", "ADD_PROD_S", "ADD_ATT_S", "ADD_SALARY",
                 "ZAHR_PROD_WORK", "ZAHR_PROD_SERV", "ZAHR_ATR_WORK", "ZAHR_ATR_SERV"]
        for r in COMPONENTS:
            attrs += [p + r["component"] for p in ("P09F4_PER_PRE_", "A09F4_PER_PRE_")]
        out = {}
        for a in attrs:
            try:
                vals = list(self.v.Net.Zones.GetMultiAttValues(a))
                # Preserve raw values and returned keys; this is read-only evidence.
                out[a] = [[str(k), str(v)] for k, v in vals]
            except Exception:
                continue
        return out

    def guard_zone_values(self):
        for a, expected in self.zone_guards.items():
            vals = [[str(k), str(v)] for k, v in self.v.Net.Zones.GetMultiAttValues(a)]
            require(vals == expected, "Frozen zone attribute changed: " + a)

    def gravity(self, no):
        return self.td.TripDistributionDStratParameters(BY_NO[no]["dstrat_code"]).GravitationParameters

    def read_abc(self):
        out = {}
        for no in BY_NO:
            g = self.gravity(no)
            out[no] = {p: number(g.AttValue("PARA_" + p.upper())) for p in ("a", "b", "c")}
        return out

    def set_abc(self, abc):
        # a and FOREIGN are never calibration writes.
        for no in MUTABLE_NOS:
            g = self.gravity(no)
            for p in ("b", "c"):
                target = float(abc[no][p])
                current = number(g.AttValue("PARA_" + p.upper()))
                if abs(current - target) > 1e-12:
                    self.model_mutated = True
                    g.SetAttValue("PARA_" + p.upper(), target)
        actual = self.read_abc()
        for no in BY_NO:
            for p in ("a", "b", "c"):
                require(abs(actual[no][p] - abc[no][p]) <= CONFIG["parameter_readback_atol"],
                        "ABC readback mismatch M%d %s: %s vs %s" % (no, p, actual[no][p], abc[no][p]))
        return actual

    def read_matrix(self, no):
        a = np.array(self.v.Net.Matrices.ItemByKey(int(no)).GetValues(), dtype=np.float64, copy=True)
        require(a.shape == (self.n, self.n), "Unexpected matrix dimensions M%d: %s" % (no, a.shape))
        require(np.isfinite(a).all(), "Non-finite matrix M%d" % no)
        return a

    def write_matrix(self, no, array):
        # Used only for native-output initialization and exact rollback, NOT OD fitting.
        self.model_mutated = True
        self.v.Net.Matrices.ItemByKey(int(no)).SetValues(array.tolist())

    def read_outputs(self):
        return {n: self.read_matrix(n) for n in MUTABLE_NOS}

    def verify_outputs(self, matrices):
        for n, expected in matrices.items():
            actual = self.read_matrix(n)
            require(sha_array(actual) == sha_array(expected), "Exact matrix restore check failed M%d" % n)

    def isolate_td(self):
        self.controls_changed = True  # cleanup must run even if a setter raises halfway
        self.td.SetAttValue("DSTRATSET", self.active_dset)
        # IMPORTANT: never disable Group operations! Keep ALL group flags unchanged.
        for r, op in zip(self.inventory, self.ops):
            if not r["is_group"]:
                want = int(r["index"] == self.td_index)
                if bool(number(op.AttValue("ACTIVE"))) != bool(want):
                    op.SetAttValue("ACTIVE", want)
        self.assert_isolated()
        self.log.event("TD_ISOLATED", "Only native TD leaf active; original groups unchanged; FOREIGN excluded")

    def assert_isolated(self):
        actual_set = {q.strip() for q in str(self.td.AttValue("DSTRATSET")).split(",") if q.strip()}
        require(actual_set == set(self.active_dset.split(",")), "TD stratum set changed unexpectedly")
        for r, op in zip(self.inventory, self.ops):
            actual = int(bool(number(op.AttValue("ACTIVE"))))
            if not r["is_group"]:
                want = int(r["index"] == self.td_index)
                require(actual == want, "Procedure ACTIVE mismatch at #%d" % r["index"])
            # Some builds derive a group checkbox from its children. Never write
            # a group flag or infer execution success from its displayed checkbox.
        require(len(get_all(self.v.Procedures.Operations)) == len(self.ops), "Procedure sequence changed during calibration")

    def restore_controls(self):
        if not self.controls_changed:
            return
        errors = []
        try:
            self.td.SetAttValue("DSTRATSET", self.original_dset)
        except Exception as exc:
            errors.append("DSTRATSET: " + repr(exc))
        for r, op in zip(self.inventory, self.ops):
            if r["is_group"]:
                continue
            try:
                if int(bool(number(op.AttValue("ACTIVE")))) != r["active"]:
                    op.SetAttValue("ACTIVE", r["active"])
            except Exception as exc:
                errors.append("ACTIVE #%d: %r" % (r["index"], exc))
        for r, op in zip(self.inventory, self.ops):
            try:
                require(int(bool(number(op.AttValue("ACTIVE")))) == r["active"], "flag mismatch")
            except Exception as exc:
                errors.append("VERIFY #%d: %r" % (r["index"], exc))
        require(not errors, "Control restore failed: " + "; ".join(errors))
        require(str(self.td.AttValue("DSTRATSET")) == self.original_dset, "DSTRATSET restore readback mismatch")
        self.controls_changed = False

    def guard_protected(self, full=False):
        self.guard_zone_values()
        nos = list(self.protected) if full else [9001, 9697, 9116]
        for no in nos:
            require(sha_array(self.read_matrix(no)) == self.protected_hashes[no], "Protected matrix changed M%d" % no)

    def execute(self):
        self.assert_isolated()
        # Clear native result destinations to prevent silently scoring stale matrices.
        # Same semantics as the checked native TD reset-result-matrices option.
        self.log.event("OUTPUT_INITIALIZATION", "Clearing only the 16 native TD result destinations")
        for no in MUTABLE_NOS:
            self.write_matrix(no, self.zero)
        self.log.event("NATIVE_TD_CALL", "Visum.Procedures.Execute(); TD-only leaf mask verified")
        self.v.Procedures.Execute()  # same entry point as user's 15A9 masters
        self.log.event("NATIVE_TD_RETURNED", "Reading regenerated native output matrices")
        matrices = self.read_outputs()
        for no, a in matrices.items():
            if float(a.sum()) <= 0:
                raise ExecutionError("TD returned no regenerated positive output in M%d. Check native TD/procedure messages; no trial accepted." % no)
            require(float(a.min()) >= -1e-10, "Negative generated trips M%d" % no)
        return matrices

    def restore_state(self, abc, matrices):
        errors = []
        try:
            self.set_abc(abc)
        except Exception as exc:
            errors.append("ABC: " + repr(exc))
        for no, a in matrices.items():
            try:
                self.write_matrix(no, a)
            except Exception as exc:
                errors.append("M%d: %r" % (no, exc))
        # Restore accidentally changed protected matrices, but never hide their failure.
        for no, a in self.protected.items():
            try:
                if sha_array(self.read_matrix(no)) != self.protected_hashes[no]:
                    self.write_matrix(no, a)
            except Exception as exc:
                errors.append("PROTECTED M%d: %r" % (no, exc))
        try:
            self.verify_outputs(matrices)
            self.guard_protected(full=True)
        except Exception as exc:
            errors.append("VERIFY: " + repr(exc))
        require(not errors, "Rollback failed: " + "; ".join(errors))

    def save_version(self, path):
        require(not Path(path).exists(), "Refusing to overwrite .ver: " + str(path))
        self.v.SaveVersion(str(path))
        require(Path(path).is_file() and Path(path).stat().st_size > 0, "SaveVersion did not produce a file")


class Metrics:
    """Native-matrix fine DIST_KM CDF comparison at all original 512 IDP nodes.

    Ordinary components use the unmodified original 512-node IDP CDF. LONG
    uses 512-node CDF of the previously accepted fixed 30-basis mixture;
    its frozen ten-bin midpoint-mean remains unchanged for comparability.

    Intrazonal distances in repaired M9697 follow the approved AMDY geometry.
    Every OD pair, including the positive intrazonal distance, enters native CDF.
    No values are imputed or changed by the calibration code.
    """
    def __init__(self, distance):
        self.cache = {}
        self.grid_cache = {}
        d = np.asarray(distance, dtype=float).ravel()
        shape = np.asarray(distance).shape
        require(len(shape) == 2 and shape[0] == shape[1], "DIST_KM must be square")
        self.n_zones = shape[0]
        require(set(FINE_AUTHORITY["targets"]) == set(TARGETS),
                "Fine IDP authority and coarse 11D/12B target block mismatch")
        require(FINE_AUTHORITY["long_reconstruction"]["max_abs_reconstruction_error"] < 1e-12,
                "LONG fine-curve reconstruction contradicts accepted frozen 12b ten-bin vector")
        for key, t in TARGETS.items():
            fine = FINE_AUTHORITY["targets"][key]
            grid_name = fine["grid"]
            fine_x = np.asarray(FINE_AUTHORITY["common_grid_%s_km" % grid_name], dtype=float)
            goal = np.asarray(fine["cdf"], dtype=float)
            require(len(fine_x) == 512 and len(goal) == 512 and
                    np.all(np.isfinite(goal)) and np.all(np.diff(goal) >= -1e-10) and
                    np.all(np.diff(fine_x) > 0) and
                    abs(goal[0]) < 1e-9 and abs(goal[-1]-1) < 1e-9,
                    "Invalid original fine target CDF: " + key)
            edges = np.asarray(t["edges"], dtype=float)
            require(abs(fine_x[-1]-edges[-1]) < 1e-9 and
                    fine_x[0] >= edges[0], "Fine target interval mismatch: " + key)
            cache_key = (float(edges[0]),float(edges[-1]),tuple(edges.tolist()),grid_name)
            if cache_key not in self.grid_cache:
                ix = np.flatnonzero((d >= edges[0]) & (d <= edges[-1]))
                x = d[ix]
                coarse_bins = np.searchsorted(edges,x,side="right")-1
                coarse_bins = np.minimum(coarse_bins,len(edges)-2)
                # Each trip contributes to empirical CDF at all following nodes.
                # Use left insertion so equality at a node is included.
                fine_bins = np.searchsorted(fine_x,x,side="left")
                require(np.max(fine_bins, initial=0) < len(fine_x),
                        "Fine CDF grid does not cover positive selected distances")
                origin_ids = ix // self.n_zones
                destination_ids = ix % self.n_zones
                self.grid_cache[cache_key] = (ix,x,coarse_bins,len(edges)-1,fine_bins,
                                              origin_ids == destination_ids)
            self.cache[key] = (self.grid_cache[cache_key],fine_x,goal)
            require(abs(sum(t["shares"])-1.0)<1e-9, "Target not normalized: " + key)

    def evaluate(self, matrices):
        out = {}
        for key,t in TARGETS.items():
            (idx,distance,bins,count,fine_bins,is_diag),fine_x,goal = self.cache[key]
            weights = np.zeros(len(idx),dtype=float)
            total = 0.0
            for no in t["matrix_nos"]:
                a = matrices[no]
                weights += a.ravel()[idx]
                total += float(a.sum())
            mass = float(weights.sum())
            require(mass > 0, "No conditioned demand in " + key)
            hist = np.bincount(bins,weights=weights,minlength=count)
            shares = hist/mass
            mean_exact = float(np.dot(weights,distance)/mass)
            if t["mean_basis"].startswith("BIN_MIDPOINT"):
                centres = (np.asarray(t["edges"][:-1])+np.asarray(t["edges"][1:]))/2
                mean = float(np.dot(shares,centres))
            else:
                mean = mean_exact
            q = np.asarray(t["shares"])
            diff = shares-q
            rel = (mean-t["mean_km"])/t["mean_km"]
            model_cdf = np.cumsum(np.bincount(fine_bins,weights=weights,minlength=len(fine_x))) / mass
            cdf_diff = model_cdf-goal
            require(abs(model_cdf[-1]-1.0)<1e-8, "Fine model CDF is not normalized: " + key)
            # The full 512-node CDF (NOT coarse histogram) is in the solver
            # residual/Jacobian. No smoothing or invented OD distances are used.
            residual = np.r_[cdf_diff/math.sqrt(len(fine_x)),
                             math.sqrt(CONFIG["shape_mean_weight"])*rel]
            zero_mass=float(np.sum(weights[distance==0])/mass)
            diag_zero_mass=float(np.sum(weights[(distance==0)&is_diag])/mass)
            offdiag_zero_mass=zero_mass-diag_zero_mass
            out[key]={"component":key, "shares":shares,"bin_volumes":hist,
                      "fine_model_cdf":model_cdf,
                      "fine_cdf_rmse":float(np.sqrt(np.mean(cdf_diff**2))),
                      "fine_cdf_mae":float(np.mean(np.abs(cdf_diff))),
                      "fine_cdf_ks":float(np.max(np.abs(cdf_diff))),
                      "fine_cdf_mean_signed":float(np.mean(cdf_diff)),
                      "fine_points_used":len(fine_x),
                      "model_cdf_at_first_idp_node":float(model_cdf[0]),
                      "target_cdf_at_first_idp_node":float(goal[0]),
                      "zero_distance_share_diagnostic":zero_mass,
                      "intrazonal_zero_distance_share_diagnostic":diag_zero_mass,
                      "offdiagonal_zero_distance_share_diagnostic":offdiag_zero_mass,
                      "zero_distance_structural_warning":int(zero_mass >= CONFIG["structural_zero_distance_warning_threshold"]),
                      "mean_model_km":mean,"mean_exact_distance_km_diagnostic":mean_exact,
                      "mean_target_km":t["mean_km"], "mean_basis":t["mean_basis"],
                      "mean_delta_km":mean-t["mean_km"],"mean_relative_error":rel,
                      "l1_half":float(.5*abs(diff).sum()),
                      "rmse_share":float(np.sqrt(np.mean(diff**2))),
                      "objective":float(residual@residual),"residual":residual,
                      "conditioned_volume_diagnostic":mass,"total_volume_diagnostic":total,
                      "conditioned_share_diagnostic":mass/total}
        return out


def write_diagnostics(folder,metrics,abc,full_fine=False):
    """Always evaluate 512 nodes; emit sparse trial curves, complete BASELINE/FINAL."""
    folder.mkdir(parents=True,exist_ok=True)
    summaries=[]; coarse_rows=[]; fine_rows=[]
    for key,m in metrics.items():
        summaries.append({k:v for k,v in m.items() if k not in
                          ("shares","residual","bin_volumes","fine_model_cdf")})
        t=TARGETS[key]
        for j,label in enumerate(t["labels"]):
            coarse_rows.append({"component":key,"metric":"DIST_KM","bin_label":label,
                                "bin_low":t["edges"][j],"bin_high":t["edges"][j+1],
                                "model_share":float(m["shares"][j]),"target_share":t["shares"][j],
                                "difference":float(m["shares"][j]-t["shares"][j]),
                                "role":"DIAGNOSTIC_ONLY_NOT_OPTIMIZATION_TARGET"})
        target=FINE_AUTHORITY["targets"][key]
        xx=FINE_AUTHORITY["common_grid_%s_km" % target["grid"]]
        yy=target["cdf"];dens=target["density"];model=m["fine_model_cdf"]
        sample_stride=max(1,int(CONFIG["fine_export_intermediate_stride"]))
        # Dense near zero / around LONG 100 km where short-distance or boundary
        # structural errors are strongest; full grid for BASELINE and FINAL.
        for j in range(len(xx)):
            if (not full_fine and j%sample_stride!=0 and j!=len(xx)-1 and
                not (j<9)):
                continue
            fine_rows.append({"component":key,"metric":"DIST_KM", "point_index":j,
                              "x_km":xx[j],"model_cdf":float(model[j]),
                              "target_cdf":yy[j],"cdf_difference":float(model[j]-yy[j]),
                              "target_density_idp":dens[j],
                              "source":target["source"],
                              "point_scope":"FULL_512" if full_fine else "TRIAL_SAMPLE_OPTIMIZED_ON_ALL_512"})
    write_csv(folder/"COMPONENT_SUMMARY.csv",summaries)
    write_csv(folder/"COMPONENT_BINS.csv",coarse_rows)
    write_csv(folder/"COMPONENT_FINE_CDF.csv",fine_rows)
    write_csv(folder/"ABC_READBACK.csv",[dict(BY_NO[n],**v) for n,v in abc.items()])


def write_fine_authority_rows(path):
    lines=[]
    for key,t in FINE_AUTHORITY["targets"].items():
        xs=FINE_AUTHORITY["common_grid_%s_km" % t["grid"]]
        for i,(x,c,dens) in enumerate(zip(xs,t["cdf"],t["density"])):
            lines.append({"component":key,"metric":"DIST_KM","point_index":i,
                          "x_km":x,"idp_target_cdf":c,"idp_target_density":dens,
                          "authority_type":t["source"],"source_scope":t["source_scope"]})
    write_csv(path,lines)

class ParameterSpace:
    def __init__(self, abc):
        self.origin = {n: dict(v) for n, v in abc.items()}
        self.x = {}; self.bounds = {}; self.probe = {}; self.trust = {}
        for key, t in TARGETS.items():
            if key == "LONG_COMPOSITE":
                self.x[key] = np.array([0.0, 0.0])
                bs = [abc[n]["b"] for n in t["matrix_nos"]]
                cs = [-abc[n]["c"] for n in t["matrix_nos"]]
                require(min(cs) > 0 and min(bs) >= 0, "LONG needs b>=0 and c<0")
                # Shared offset b and shared multiplicative c, not five unrelated targets.
                self.bounds[key] = np.array([[-min(bs), 10.0-max(bs)],
                                              [math.log(1/4), math.log(4)]])
                self.probe[key] = np.array([0.08, math.log(1.06)])
                self.trust[key] = np.array([0.20, math.log(1.15)])
            else:
                n = t["matrix_nos"][0]
                b, c = abc[n]["b"], abc[n]["c"]
                require(b >= 0 and c < 0, "Combined gravity requires b>=0 and c<0 for " + key)
                self.x[key] = np.array([b, math.log(-c)])
                # Existing values are never snapped to an envelope.
                self.bounds[key] = np.array([[0.0, max(4.0, b)],
                                              [min(math.log(0.001), math.log(-c)), max(math.log(8.0), math.log(-c))]])
                self.probe[key] = np.array([0.05, math.log(1.06)])
                self.trust[key] = np.array([0.25, math.log(1.25)])

    def abc(self, x):
        out = {n: dict(v) for n, v in self.origin.items()}
        for key, v in x.items():
            if key == "LONG_COMPOSITE":
                for n in TARGETS[key]["matrix_nos"]:
                    out[n]["b"] = self.origin[n]["b"] + float(v[0])
                    out[n]["c"] = self.origin[n]["c"] * math.exp(float(v[1]))
            else:
                n = TARGETS[key]["matrix_nos"][0]
                out[n]["b"] = float(v[0])
                out[n]["c"] = -math.exp(float(v[1]))
        return out

    def perturb(self, x, axis, radius):
        trial = {k: v.copy() for k, v in x.items()}
        delta = {}
        for k in GROUPS:
            lo, hi = self.bounds[k][axis]
            h = min(self.probe[k][axis], self.trust[k][axis] * radius[k])
            if x[k][axis] + h <= hi:
                step = h
            elif x[k][axis] - h >= lo:
                step = -h
            else:
                step = (hi - x[k][axis]) if hi-x[k][axis] >= x[k][axis]-lo else lo-x[k][axis]
            require(abs(step) > 1e-12, "No room for finite difference: " + k)
            trial[k][axis] += step
            delta[k] = step
        return trial, delta

    def candidate(self, x, base, bp, cp, db, dc, radius):
        out = {}
        audit = []
        predicted = {}
        for key in GROUPS:
            r = base[key]["residual"]
            j = np.column_stack(((bp[key]["residual"] - r) / db[key],
                                 (cp[key]["residual"] - r) / dc[key]))
            scale = self.trust[key] * radius[key]
            a = j * scale[None, :]
            h = a.T @ a
            h += np.eye(2) * (1e-6 + 1e-3 * float(np.trace(h)))
            g = a.T @ r
            lo = np.maximum(-1.0, (self.bounds[key][:, 0] - x[key]) / scale)
            hi = np.minimum(1.0, (self.bounds[key][:, 1] - x[key]) / scale)
            z = box_quadratic_2d(h, g, lo, hi)
            delta = z * scale
            out[key] = x[key] + delta
            pred_residual = r + j @ delta
            predicted[key] = float(pred_residual @ pred_residual)
            for i in [j for j in range(len(r)) if j < 9 or j % 16 == 0 or j == len(r)-1]:
                audit.append({"component": key, "residual_index": i, "residual": r[i],
                              "d_residual_db": j[i, 0], "d_residual_dlog_minus_c": j[i, 1],
                              "b_probe_step": db[key], "log_minus_c_probe_step": dc[key],
                              "trust_factor": radius[key]})
        return out, audit, predicted


def box_quadratic_2d(h, g, lo, hi):
    """Exact small box-constrained positive-definite quadratic: interior + faces."""
    options = [np.maximum(lo, np.minimum(hi, np.zeros(2)))]
    try:
        z = -np.linalg.solve(h, g)
        if np.all(z >= lo) and np.all(z <= hi):
            options.append(z)
    except np.linalg.LinAlgError:
        pass
    for axis in (0, 1):
        other = 1-axis
        for edge in (lo[axis], hi[axis]):
            z = np.zeros(2); z[axis] = edge
            z[other] = np.clip(-(g[other]+h[other, axis]*edge)/h[other, other], lo[other], hi[other])
            options.append(z)
    return min(options, key=lambda z: float(0.5*z@h@z + g@z)).copy()


def acceptable(before, after, strict=True):
    improvement = before["objective"] - after["objective"]
    tol = max(CONFIG["minimum_objective_improvement"], before["objective"] * 1e-6)
    if strict and improvement <= tol:
        return False
    if not strict and improvement < -tol:
        return False
    if after["fine_cdf_rmse"] > before["fine_cdf_rmse"] + CONFIG["max_fine_cdf_rmse_degradation"]:
        return False
    allowed_mean = max(abs(before["mean_relative_error"]), CONFIG["mean_error_floor"])
    return abs(after["mean_relative_error"]) <= allowed_mean + CONFIG["max_mean_error_degradation"]



# A native PTV gravity TD may be constrained on productions OR attractions.
# Baseline OD output is not proof that BOTH margins are constraints. Infer a
# stable side from a genuine (b,c) perturbation, independently for each DStrat.
# This is inferred behavior, NOT COM readback of the GUI's Direction setting.
MARGINAL_MODE_ATTRACTION = "ATTRACTION_CONSTRAINED_INFERRED"
MARGINAL_MODE_PRODUCTION = "PRODUCTION_CONSTRAINED_INFERRED"
MARGINAL_MODE_UNDECIDED = "UNDETERMINED_BOTH_SIDES_STABLE"


def audit_native_marginals(reference, trial_matrices, prior_modes, zone_order):
    """Evaluate preserved totals and the actually constrained margin only.

    Standard matrix convention: origins on rows (axis=1), destinations on
    columns (axis=0). Output on the UNconstrained side is measured but is NOT
    used as a reject condition, because it is expected to redistribute.

    If no axis passes the baseline boundary-sum tolerance, FAIL CLOSED rather
    than inventing a distribution constraint. If a detected constrained axis
    changes later, FAIL CLOSED. Each conclusion is matrix-specific.

    Returns audit_rows, worst_zones, failures, candidate_modes, mode_rows.
    Candidate modes must only be committed by the caller when failures empty.
    """
    require(set(reference) == set(trial_matrices),
            "Native TD result matrices do not match baseline component scope")
    audit_rows, worst_zones, failures, candidate_modes, mode_rows = [], [], [], {}, []
    for no, array in trial_matrices.items():
        ref_dest, ref_orig = reference[no]
        ref_total = float(np.sum(ref_dest))
        got_total = float(np.sum(array))
        total_tol = CONFIG["total_atol"] + CONFIG["total_rtol"] * abs(ref_total)
        total_delta = got_total - ref_total
        total_ok = abs(total_delta) <= total_tol

        test = {}
        for ax, ref in ((0, ref_dest), (1, ref_orig)):
            got = np.sum(array, axis=ax)
            d = got - ref
            ad = np.abs(d)
            tol = CONFIG["marginal_atol"] + CONFIG["marginal_rtol"] * np.abs(ref)
            outside = ad > tol
            test[ax] = {"reference":ref, "trial":got, "delta":d,
                        "abs_delta":ad, "tol":tol, "outside":outside,
                        "stable":bool(not np.any(outside))}

        old_mode = prior_modes.get(no)
        if old_mode == MARGINAL_MODE_ATTRACTION:
            mode = old_mode
            enforced = (0,)
        elif old_mode == MARGINAL_MODE_PRODUCTION:
            mode = old_mode
            enforced = (1,)
        elif old_mode in (None, MARGINAL_MODE_UNDECIDED):
            d_ok, o_ok = test[0]["stable"], test[1]["stable"]
            if d_ok and not o_ok:
                mode = MARGINAL_MODE_ATTRACTION
                enforced = (0,)
            elif o_ok and not d_ok:
                mode = MARGINAL_MODE_PRODUCTION
                enforced = (1,)
            elif d_ok and o_ok:
                mode = MARGINAL_MODE_UNDECIDED
                enforced = (0, 1)
            else:
                mode = "NO_STABLE_MARGIN_REJECT"
                enforced = (0, 1)
        else:
            raise GuardError("Unknown persisted constraint inference for M%d: %s" % (no, old_mode))

        candidate_modes[no] = mode
        mode_rows.append({
            "matrix_no": int(no), "component": BY_NO.get(int(no), {}).get("component", ""),
            "previous_inferred_mode":old_mode or MARGINAL_MODE_UNDECIDED,
            "candidate_inferred_mode":mode,
            "destination_stable":int(test[0]["stable"]),
            "origin_stable":int(test[1]["stable"]),
            "total_stable":int(total_ok),
            "enforced_axes":",".join(str(a) for a in enforced),
            "evidence":"Measured native TD output under b/c perturbation; not COM GUI setting"
        })
        if not total_ok:
            failures.append((int(no), "TOTAL", 1, float(abs(total_delta)),
                             float(abs(total_delta) / max(total_tol, 1e-12))))
        for ax in (0, 1):
            item = test[ax]
            ad, tol, outside = item["abs_delta"], item["tol"], item["outside"]
            bad_n = int(np.count_nonzero(outside))
            is_enforced = ax in enforced
            severity = float(np.max(ad / np.maximum(tol, 1e-12)))
            reject_this_axis = bool(is_enforced and bad_n)
            if reject_this_axis:
                failures.append((int(no), int(ax), bad_n, float(np.max(ad)), severity))
            audit_rows.append({
                "matrix_no":int(no),
                "component":BY_NO.get(int(no), {}).get("component", ""),
                "sum_axis":ax,
                "margin_type":"DESTINATIONS" if ax == 0 else "ORIGINS",
                "previous_inferred_mode":old_mode or MARGINAL_MODE_UNDECIDED,
                "candidate_inferred_mode":mode,
                "constraint_enforced":int(is_enforced),
                "constraint_status":("REJECT_CONSTRAINED_SIDE" if reject_this_axis
                    else "FREE_AXIS_DIAGNOSTIC_ONLY" if not is_enforced
                    else "CONSTRAINED_SIDE_OK"),
                "reference_total":ref_total,
                "trial_total":got_total,
                "total_delta":total_delta,
                "total_within_tolerance":int(total_ok),
                "max_abs_difference":float(ad.max()),
                "sum_abs_difference":float(ad.sum()),
                "sum_abs_as_fraction_of_total":float(ad.sum()/max(abs(ref_total), 1.0)),
                "max_relative_difference_at_least_1_trip":float(np.max(ad / np.maximum(np.abs(item["reference"]),1.0))),
                "failed_zone_count_vs_stability_tolerance":bad_n,
                "all_zones_within_tolerance":int(item["stable"]),
                "hard_guard_failure":int(reject_this_axis),
                "max_tolerance_multiple":severity,
            })
            # Forensic export even if the margin is free: this is behavior, not
            # an error, and must be available for later production diagnostics.
            if bad_n:
                ratio = ad / np.maximum(tol, 1e-12)
                sample = set(np.argsort(-ratio)[:12].tolist()) | set(np.argsort(-ad)[:12].tolist())
                for k in sorted(sample):
                    if not outside[k]:
                        continue
                    worst_zones.append({
                        "matrix_no":int(no), "sum_axis":ax,
                        "margin_type":"DESTINATIONS" if ax == 0 else "ORIGINS",
                        "zone_no":int(zone_order[int(k)]),
                        "reference":float(item["reference"][k]),
                        "trial":float(item["trial"][k]),
                        "delta":float(item["delta"][k]),
                        "abs_delta":float(ad[k]),
                        "stability_tolerance":float(tol[k]),
                        "ratio_to_stability_tolerance":float(ratio[k]),
                        "constraint_enforced":int(is_enforced),
                        "hard_guard_failure":int(reject_this_axis),
                        "interpretation":("CHECK_FAILED" if reject_this_axis
                            else "EXPECTED_MOVEMENT_ON_UNCONSTRAINED_SIDE" if not is_enforced
                            else "WITHIN_STABILITY_TOLERANCE"),
                    })
    return audit_rows, worst_zones, failures, candidate_modes, mode_rows


class Runner:
    def __init__(self, adapter, log):
        self.adapter, self.log = adapter, log
        self.space = ParameterSpace(adapter.entry_abc)
        self.metrics = Metrics(adapter.protected[CONFIG["distance_matrix"]])
        write_json(log.root / "03_PARAMETER_SPACE.json", {
            "initial_x": self.space.x, "bounds": self.space.bounds, "probe_steps": self.space.probe,
            "trust_steps": self.space.trust, "coordinates": "Atomic: b, log(-c); LONG: shared b offset, log(c multiplier)",
            "objective": "RMSE_CDF_512_POINT**2 + 0.25 * relative_mean_error**2; equal block weights; 6bin/10bin L1 diagnostic only"})
        self.evaluations = 0
        self.best = None
        self.baseline = None
        self.marginals = None
        self.marginal_modes = {}  # persisted only after a fully valid native response

    def evaluate(self, x, label, honor_stop=True):
        if honor_stop:
            self.log.check_stop(self.evaluations)
        self.evaluations += 1
        folder = self.log.root / ("EVAL_%03d_%s" % (self.evaluations, label))
        folder.mkdir()
        abc = self.space.abc(x)
        self.log.summary["td_evaluations"] = self.evaluations
        self.log.event("TD_EXECUTION_START", "%03d %s" % (self.evaluations, label))
        before_time = time.monotonic()
        self.log.event("PARAMETER_WRITE", label)
        applied = self.adapter.set_abc(abc)
        write_csv(folder / "PARAMETERS_BEFORE_TD.csv", [dict(BY_NO[n], **v) for n, v in applied.items()])
        arrays = self.adapter.execute()
        # Verify that native settings such as 'apply estimated parameters' did not override b/c.
        actual = self.adapter.read_abc()
        for n in BY_NO:
            for p in ("a", "b", "c"):
                require(abs(actual[n][p] - abc[n][p]) <= CONFIG["parameter_readback_atol"],
                        "Native TD changed requested parameter: M%d/%s" % (n, p))
        self.adapter.guard_protected(full=self.evaluations % CONFIG["guard_every_n_evaluations"] == 0)
        # Audit BOTH margin vectors for all 16 output matrices. The native
        # calculation can be singly constrained: only its invariant margin
        # belongs in the hard guard; the other can naturally redistribute.
        if self.marginals is not None:
            (marginal_audit, worst_zones, failures, candidate_modes,
             mode_rows) = audit_native_marginals(
                self.marginals, arrays, self.marginal_modes,
                self.adapter.zone_order)
        else:
            marginal_audit, worst_zones, failures, candidate_modes, mode_rows = [], [], [], {}, []
        write_csv(folder / "MARGINAL_GUARD.csv", marginal_audit)
        write_csv(folder / "MARGINAL_WORST_ZONES.csv", worst_zones)
        write_csv(folder / "MARGINAL_CONSTRAINT_INFERENCE.csv", mode_rows)
        if failures:
            worst = max(failures, key=lambda f: f[4])
            info = {
                "status":"REJECTED_ENFORCED_MARGIN_OR_TOTAL_GUARD",
                "evaluation":self.evaluations, "label":label,
                "number_of_failed_checks":len(failures),
                "first_failure":failures[0], "largest_tolerance_multiple":worst,
                "marginal_rtol_for_constrained_side":CONFIG["marginal_rtol"],
                "marginal_atol_for_constrained_side":CONFIG["marginal_atol"],
                "total_rtol":CONFIG["total_rtol"],
                "constraint_inference":"Measured output: destination-only, origin-only, both-stable or no-stable-side. Not COM GUI readback.",
                "note":"Unconstrained OD margin drift is diagnostic only. P/A source attributes, native TD outputs and protected FOREIGN are independently guarded."
            }
            write_json(folder / "MARGINAL_FAILURE.json", info)
            self.log.summary["latest_marginal_failure"] = dict(info, folder=str(folder))
            f = failures[0]
            raise MarginalGuardError(
                "Enforced native TD constraint failed M%d side=%s, %d zones; max abs %g, tolerance multiple %g; see %s" %
                (f[0],str(f[1]),f[2],f[3],f[4],str(folder / "MARGINAL_GUARD.csv")))
        # Inference is committed only after all 16 matrices pass the true
        # constraints AND unchanged source/protected-data guards.
        if candidate_modes:
            discoveries = []
            for no, mode in candidate_modes.items():
                old = self.marginal_modes.get(no)
                if old != mode:
                    discoveries.append("M%d:%s" % (no,mode))
                self.marginal_modes[no] = mode
            write_csv(self.log.root / "MARGINAL_MODES.csv", [
                {"matrix_no":no, "component":BY_NO[no]["component"],
                 "observed_constraint_mode":self.marginal_modes[no],
                 "evidence":"Inferred from one or more native TD perturbations; not GUI metadata"}
                for no in sorted(self.marginal_modes)])
            self.log.summary["inferred_td_constraint_modes"] = {
                str(no):mode for no,mode in self.marginal_modes.items()}
            if discoveries:
                self.log.event("MARGINAL_CONSTRAINT_INFERRED", ", ".join(discoveries))
        scores = self.metrics.evaluate(arrays)
        write_diagnostics(folder, scores, actual)
        result = {"x": {k: v.copy() for k, v in x.items()}, "abc": actual,
                  "matrices": arrays, "metrics": scores, "folder": str(folder), "label": label}
        write_json(folder / "EXECUTION.json", {"phase": "TD_EXECUTED_AND_MEASURED", "seconds": time.monotonic()-before_time,
                   "output_hashes": {n: sha_array(a) for n, a in arrays.items()},
                   "td_metadata": {a: safe_att(self.adapter.ops[self.adapter.td_index-1], a)
                                   for a in ("SUCCESS", "STARTTIME", "DURATION", "RESULTMESSAGE")}})
        self.log.event("TD_EXECUTED_AND_MEASURED", "%03d %s; Jsum=%.9g" % (self.evaluations, label, sum(m["objective"] for m in scores.values())))
        return result

    def checkpoint(self, state):
        # Consistent versioned snapshot; metadata is committed AFTER the payload.
        tag = "ACCEPTED_%03d" % self.evaluations
        path = self.log.root / (tag + ".npz")
        dump_arrays(path, state["matrices"])
        write_json(self.log.root / "BEST_STATE.json", {"matrix_file": path.name, "matrix_sha256": sha_file(path),
                   "abc": state["abc"], "x": state["x"], "evaluation": self.evaluations,
                   "source_folder": state["folder"], "status": "NATIVE_TD_MEASURED_ACCEPTED"})
        self.log.summary["best_state_file"] = str(path)
        # Keep current and one prior accepted array snapshot. Do not remove versions.
        snapshots = sorted(self.log.root.glob("ACCEPTED_*.npz"))
        for old in snapshots[:-2]:
            old.unlink()

    def probe_with_backoff(self, base, proposal, label):
        """Measure a native-constraint-valid finite difference or halt.

        Backoff is numerical: only enforced margins/totals cause rejection. Each failed
        attempt restores the actual accepted matrices and ABC before retry.
        """
        x = base["x"]
        factor = 1.0
        last_error = ""
        for attempt in range(1, CONFIG["max_marginal_probe_attempts"]+1):
            trial_x = {k: x[k] + factor * (proposal[k]-x[k]) for k in GROUPS}
            tag = "%s_H%02d" % (label, attempt)
            try:
                result = self.evaluate(trial_x, tag)
                self.log.event("MARGINAL_PROBE_OK", "%s, scale=%g" % (tag, factor))
                delta = {k: float(trial_x[k][0 if "PROBE_B" in label else 1] -
                                  x[k][0 if "PROBE_B" in label else 1]) for k in GROUPS}
                return result, delta
            except MarginalGuardError as exc:
                last_error = str(exc)
                self.log.event("MARGINAL_PROBE_REJECTED_BACKOFF", "%s scale=%g %s" % (tag,factor,last_error))
                self.adapter.restore_state(base["abc"], base["matrices"])
                factor *= CONFIG["marginal_backoff_factor"]
        raise MarginalCalibrationHalt(
            "%s failed enforced native TD constraint at all %d scales; no new parameters accepted. Last: %s" %
            (label,CONFIG["max_marginal_probe_attempts"],last_error))

    def optimize(self):
        # A fresh baseline is mandatory; earlier supplied 11d/probe files are not runtime state.
        baseline = self.evaluate(self.space.x, "BASELINE")
        self.best = baseline
        self.baseline = baseline
        self.marginals = {n: [a.sum(axis=0), a.sum(axis=1)] for n, a in baseline["matrices"].items()}
        self.checkpoint(baseline)
        self.log.summary["calibration_baseline"] = "FRESH_NATIVE_TD_AFTER_2022_OSRM_AMDY_INPUT_PATCH"
        self.log.summary["fresh_baseline_objective_sum"] = float(sum(m["objective"] for m in baseline["metrics"].values()))
        self.log.summary["entry_od_matrices_treated_as_stale"] = True
        self.log.event("FRESH_BASELINE_VERIFIED", "New native TD baseline after OSRM/AMDY patch; Jsum=%.9g" % self.log.summary["fresh_baseline_objective_sum"])
        write_diagnostics(self.log.root / "BASELINE", baseline["metrics"], baseline["abc"], full_fine=True)
        # Patched M9697 has positive AMDY intrazonal distances. Measure any
        # unexpected remaining zero-distance mass rather than assuming old data.
        zero_audit = [{"component":k,
                       "model_zero_distance_share":v["zero_distance_share_diagnostic"],
                       "intrazonal_zero_distance_share":v["intrazonal_zero_distance_share_diagnostic"],
                       "offdiagonal_zero_distance_share":v["offdiagonal_zero_distance_share_diagnostic"],
                       "model_cdf_at_first_target_node":v["model_cdf_at_first_idp_node"],
                       "target_cdf_at_first_target_node":v["target_cdf_at_first_idp_node"],
                       "structural_warning":v["zero_distance_structural_warning"],
                       "warning_reason":"UNEXPECTED_ZERO_DISTANCE_MASS_AFTER_APPROVED_AMDY_PATCH" if v["zero_distance_structural_warning"] else "NONE"}
                      for k,v in baseline["metrics"].items()]
        write_csv(self.log.root / "STRUCTURAL_ZERO_DISTANCE_BASELINE.csv",zero_audit)
        affected = [r["component"] for r in zero_audit if r["structural_warning"]]
        if affected:
            self.log.summary["fine_curve_structural_zero_distance_warning_components"] = affected
            self.log.summary["fine_curve_structural_zero_distance_interpretation"] = (
                "Unexpected 0 km travel observed after AMDY/OSRM input repair; inspect M9697 before accepting fit.")
            self.log.event("STRUCTURAL_ZERO_DISTANCE_WARNING",
                           "%d groups: unexpected 0 km OD volume remains in patched M9697" % len(affected))
        radius = {k: 1.0 for k in GROUPS}
        stagnant = 0
        reason = "MAX_ITERATIONS"
        for iteration in range(1, CONFIG["max_iterations"] + 1):
            self.log.check_stop(self.evaluations)
            base = self.best
            x = base["x"]
            bx, db = self.space.perturb(x, 0, radius)
            cx, dc = self.space.perturb(x, 1, radius)
            b, db = self.probe_with_backoff(base, bx, "I%02d_PROBE_B" % iteration)
            c, dc = self.probe_with_backoff(base, cx, "I%02d_PROBE_C" % iteration)
            gx, jac, predicted = self.space.candidate(
                x, base["metrics"], b["metrics"], c["metrics"], db, dc, radius)
            write_csv(self.log.root / ("ITER_%02d_JACOBIAN.csv" % iteration), jac)
            active = set()
            for k in GROUPS:
                before_obj = float(base["metrics"][k]["objective"])
                rel = (before_obj-float(predicted[k]))/max(abs(before_obj), 1e-12)
                if rel >= CONFIG["active_block_predicted_relative_improvement"]:
                    active.add(k)
            self.log.summary["last_predicted_active_blocks"] = sorted(active)
            options = [b, c]
            # Avoid retaining several full matrix snapshots: only metrics and parameters
            # are needed until the chosen combination is regenerated and verified.
            for option in options:
                option.pop("matrices", None)
            line_search_evaluated = 0
            for alpha in CONFIG["line_search"]:
                trial_x = {k: x[k] + alpha * (gx[k]-x[k]) for k in GROUPS}
                if max(np.max(abs(trial_x[k]-x[k])) for k in GROUPS) < 1e-10:
                    continue
                try:
                    trial = self.evaluate(trial_x, "I%02d_LS_%s" % (iteration, str(alpha).replace(".", "p")))
                except MarginalGuardError as exc:
                    self.log.event("LINESEARCH_REJECTED_MARGINAL", "iteration %d alpha=%s: %s" % (iteration, alpha, exc))
                    self.adapter.restore_state(base["abc"], base["matrices"])
                    continue
                trial.pop("matrices", None)
                options.append(trial)
                line_search_evaluated += 1
                # Already have a valid improvement for every improvable block: do not
                # spend more evaluations merely seeking a smaller line-search step.
                # Blocks with no predicted local decrease may remain at the accepted
                # parent; final combined verification still protects every block.
                if ((not active and line_search_evaluated >= 1) or
                        all(any(acceptable(base["metrics"][k], o["metrics"][k])
                                for o in options) for k in active)):
                    break
            chosen = {}
            for k in GROUPS:
                good = [o for o in options if acceptable(base["metrics"][k], o["metrics"][k])]
                chosen[k] = min(good, key=lambda o: o["metrics"][k]["objective"]) if good else base
            next_x = {k: chosen[k]["x"][k].copy() for k in GROUPS}
            improved = [k for k in GROUPS if chosen[k] is not base]
            accepted = False
            after = base
            if improved:
                # Do not synthesize an 'accepted OD matrix' by mixing bins/cells.
                # Re-run native TD on the whole combined vector; verify every block.
                try:
                    verified = self.evaluate(next_x, "I%02d_VERIFY_COMBINED" % iteration)
                except MarginalGuardError as exc:
                    self.log.event("COMBINED_REJECTED_MARGINAL", "iteration %d: %s" % (iteration,exc))
                    verified = None
                if verified is not None:
                    safe = all(acceptable(base["metrics"][k], verified["metrics"][k], strict=False) for k in GROUPS)
                    better = sum(m["objective"] for m in verified["metrics"].values()) < sum(m["objective"] for m in base["metrics"].values()) - CONFIG["minimum_objective_improvement"]
                    mismatch = max(float(np.max(abs(verified["metrics"][k]["shares"]-chosen[k]["metrics"][k]["shares"]))) for k in GROUPS)
                    if safe and better:
                        self.best = verified
                        self.checkpoint(verified)
                        after = verified
                        accepted = True
                    self.log.summary["last_combined_separability_share_error"] = mismatch
            if not accepted:
                self.adapter.restore_state(base["abc"], base["matrices"])
                stagnant += 1
            else:
                stagnant = 0
            for k in GROUPS:
                if accepted and k in improved:
                    scale = self.space.trust[k] * radius[k]
                    step_fraction = float(np.max(np.abs(next_x[k]-x[k]) /
                                          np.maximum(np.abs(scale), 1e-12)))
                    growth = (CONFIG["trust_growth_boundary"] if step_fraction >= 0.8
                              else CONFIG["trust_growth_regular"])
                    radius[k] = min(CONFIG["trust_radius_max"], radius[k]*growth)
                else:
                    radius[k] = max(CONFIG["trust_radius_min"],
                                    radius[k]*CONFIG["trust_shrink_rejected"])
            for k in GROUPS:
                bm, am = base["metrics"][k], after["metrics"][k]
                self.log.history.append({"iteration": iteration, "component": k,
                    "status": "ACCEPTED" if accepted and k in improved else "KEPT_PREVIOUS",
                    "source_trial": chosen[k]["label"] if accepted else base["label"],
                    "before_objective": bm["objective"], "after_objective": am["objective"],
                    "before_l1_half": bm["l1_half"], "after_l1_half": am["l1_half"],
                    "before_fine_cdf_rmse":bm["fine_cdf_rmse"],"after_fine_cdf_rmse":am["fine_cdf_rmse"],
                    "before_mean_km": bm["mean_model_km"], "after_mean_km": am["mean_model_km"],
                    "target_mean_km": am["mean_target_km"], "mean_basis": am["mean_basis"],
                    "predicted_objective": predicted[k],
                    "predicted_active": int(k in active),
                    "next_trust_factor": radius[k], "td_evaluations": self.evaluations})
            write_csv(self.log.root / "ITERATION_HISTORY.csv", self.log.history)
            self.log.summary.update({"iterations_completed": iteration, "stagnant_iterations": stagnant})
            self.log.event("ACCEPTED" if accepted else "REJECTED_ROLLBACK_CONTINUE", "iteration %d; changed blocks=%s" % (iteration, ",".join(improved) if accepted else "none"))
            if stagnant >= CONFIG["max_stagnant_iterations"]:
                reason = "LOCAL_PLATEAU_NOT_PROOF_OF_GLOBAL_OPTIMUM"
                break
        return reason


def write_final_comparison(log, runner):
    # Entry OD matrices were stale when the OSRM/AMDY input patch was applied.
    # Compare ONLY to a freshly regenerated native TD baseline from patched inputs.
    start = runner.baseline["metrics"]
    best = runner.best
    rows = []
    for key in GROUPS:
        a, b = start[key], best["metrics"][key]
        fresh = runner.baseline["metrics"][key]
        rows.append({"component": key,
                     "input_semantics":"FRESH_NATIVE_TD_ON_PATCHED_2022_INPUTS_NOT_PREPATCH_STALE_OD",
                     "input_mean": a["mean_model_km"], "final_mean": b["mean_model_km"],
                     "target_mean": b["mean_target_km"], "mean_basis": b["mean_basis"],
                     "fresh_baseline_mean": fresh["mean_model_km"],
                     "fresh_baseline_l1_half": fresh["l1_half"], "fresh_baseline_objective": fresh["objective"],
                     "input_l1_half": a["l1_half"], "final_l1_half": b["l1_half"],
                     "input_fine_cdf_rmse":a["fine_cdf_rmse"],
                     "final_fine_cdf_rmse":b["fine_cdf_rmse"],
                     "target_fine_grid_nodes":b["fine_points_used"],
                     "final_fine_cdf_ks":b["fine_cdf_ks"],
                     "final_zero_distance_share":b["zero_distance_share_diagnostic"],
                     "final_intrazonal_zero_share":b["intrazonal_zero_distance_share_diagnostic"],
                     "input_objective": a["objective"], "final_objective": b["objective"],
                     "final_abs_relative_mean_error": abs(b["mean_relative_error"])})
    write_csv(log.root / "FINAL_VS_INPUT.csv", rows)
    final = []
    for no in BY_NO:
        initial = runner.adapter.entry_abc[no]
        values = best["abc"][no]
        final.append(dict(BY_NO[no], initial_a=initial["a"], initial_b=initial["b"], initial_c=initial["c"],
                          final_a=values["a"], final_b=values["b"], final_c=values["c"],
                          delta_b=values["b"]-initial["b"], delta_c=values["c"]-initial["c"]))
    write_csv(log.root / "FINAL_PARAMETERS.csv", final)
    write_diagnostics(log.root / "FINAL", best["metrics"], best["abc"], full_fine=True)


def evidence_zip(root):
    dest = root.parent / (root.name + "_EVIDENCE.zip")
    with zipfile.ZipFile(dest, "w", zipfile.ZIP_DEFLATED) as z:
        for p in sorted(root.rglob("*")):
            if p.is_file() and p.suffix.lower() not in (".ver", ".verx", ".npz", ".tmp"):
                z.write(p, str(p.relative_to(root)))
    return str(dest)


def main(visum=None, output_root=None):
    parent = Path(output_root) if output_root is not None else default_output_root()
    root = parent / ("RUN_" + datetime.now().strftime("%Y%m%d_%H%M%S_%f"))
    root.mkdir(parents=True, exist_ok=False)
    preflight_output_storage(root)
    log = Log(root)
    log.summary["evidence_root_policy"] = (
        "EXPLICIT_CALLER_OVERRIDE" if output_root is not None else
        "LOCALAPPDATA_UNSYNCED" if os.environ.get("LOCALAPPDATA", "").strip() else
        "LOCAL_TEMP_UNSYNCED_FALLBACK")
    adapter = runner = silent = None
    lock = parent / "R1_BC_AUTO.lock"
    have_lock = False
    run_error = None
    try:
        require(np is not None, "NumPy is unavailable in this Visum Python environment")
        try:
            fd = os.open(str(lock), os.O_WRONLY | os.O_CREAT | os.O_EXCL)
        except FileExistsError:
            raise GuardError("Another run or stale lock exists: %s. Remove only after checking no calibration is running." % lock)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump({"pid": os.getpid(), "run": str(root), "started": timestamp()}, f)
        have_lock = True
        write_json(root / "TARGETS_USED.json", AUTHORITY)
        write_json(root / "FINE_IDP_AUTHORITY_512.json", FINE_AUTHORITY)
        write_fine_authority_rows(root / "FINE_IDP_AUTHORITY_512.csv")
        log.summary["fine_curve_authority_sha256"] = hashlib.sha256(json.dumps(FINE_AUTHORITY, sort_keys=True).encode()).hexdigest()
        log.summary["calibration_objective"] = "512_POINT_ORIGINAL_IDP_CDF_PLUS_MEAN__HISTOGRAM_DIAGNOSTIC_ONLY"
        log.summary["patched_input_required"] = True
        log.summary["comparison_baseline_semantics"] = "FRESH_NATIVE_TD_AFTER_2022_AMDY_OSRM_REPAIR"
        log.summary["authority_sha256"] = hashlib.sha256(json.dumps(AUTHORITY, sort_keys=True).encode()).hexdigest()
        current_visum = visum if visum is not None else live_visum()
        silent = SilentProcedureWarnings(current_visum, log)
        silent.enable()  # FAIL CLOSED before a single matrix/parameter/operation write
        adapter = VisumAdapter(current_visum, log)
        # Backup before ANY parameter/flag/matrix initialization write.
        initial = dict(adapter.protected); initial.update(adapter.initial_matrices)
        dump_arrays(root / "START_STATE.npz", initial)
        write_json(root / "START_STATE.json", {"abc": adapter.entry_abc,
                   "matrix_file": "START_STATE.npz", "matrix_sha256": sha_file(root / "START_STATE.npz"),
                   "inventory": adapter.inventory, "dstratset": adapter.original_dset})
        if CONFIG["save_versions"]:
            adapter.save_version(root / "00_START_SAFETY.ver")
            log.summary["start_safety_version"] = str(root / "00_START_SAFETY.ver")
        runner = Runner(adapter, log)
        adapter.isolate_td()
        reason = runner.optimize()
        log.summary.update({"status": "COMPLETED", "stop_reason": reason})
    except StopRequested as exc:
        log.summary.update({"status": "STOPPED_WITH_BEST_STATE", "stop_reason": str(exc)})
    except MarginalCalibrationHalt as exc:
        log.summary.update({"status": "STOPPED_ENFORCED_MARGINALS_UNRESOLVED",
                            "stop_reason": str(exc), "error_phase": log.phase})
        log.event("ENFORCED_MARGINAL_PROBES_EXHAUSTED", str(exc))
    except BaseException as exc:
        run_error = exc
        log.summary.update({"status": "FAILED", "error_phase": log.phase,
                            "error": repr(exc), "traceback": traceback.format_exc()})
        log.event("FAILURE", repr(exc))
    finally:
        if adapter is not None:
            try:
                state = runner.best if runner is not None else None
                if not adapter.model_mutated:
                    adapter.verify_outputs(adapter.initial_matrices)
                    adapter.guard_protected(full=True)
                    log.summary["model_state_after_exit"] = "INPUT_NOT_MUTATED"
                elif state is not None:
                    adapter.restore_state(state["abc"], state["matrices"])
                    log.summary["model_state_after_exit"] = "BEST_ACCEPTED_DISTRIBUTION_ONLY"
                else:
                    adapter.restore_state(adapter.entry_abc, adapter.initial_matrices)
                    log.summary["model_state_after_exit"] = "EXACT_INPUT_MATRICES_AND_ABC"
                log.summary["matrix_and_abc_restore_verified"] = True
            except BaseException as exc:
                log.summary["restore_error"] = repr(exc)
                log.summary["status"] = "FAILED_RESTORE_REQUIRES_ATTENTION"
                log.summary["matrix_and_abc_restore_verified"] = False
            try:
                adapter.restore_controls()
                log.summary["original_controls_restored"] = True
            except BaseException as exc:
                log.summary["control_restore_error"] = repr(exc)
                log.summary["status"] = "FAILED_RESTORE_REQUIRES_ATTENTION"
            if runner is not None and runner.best is not None and log.summary.get("matrix_and_abc_restore_verified") and log.summary.get("original_controls_restored"):
                try:
                    write_final_comparison(log, runner)
                    if CONFIG["save_versions"]:
                        path = root / "FINAL_DISTRIBUTION_ONLY.ver"
                        adapter.save_version(path)
                        log.summary["final_distribution_version"] = str(path)
                    log.summary["downstream_status"] = "STALE_NOT_REBUILT: realization/smart_sym/assignment must follow before production use"
                    log.summary["final_objective_sum"] = sum(m["objective"] for m in runner.best["metrics"].values())
                except BaseException as exc:
                    log.summary["final_export_error"] = repr(exc)
                    log.summary["status"] = "FAILED_FINAL_EXPORT_BEST_STATE_RESTORED"
        if silent is not None:
            try:
                silent.restore()
                log.summary["native_warning_preferences_restored"] = True
            except BaseException as exc:
                log.summary["native_warning_preferences_restore_error"] = repr(exc)
                log.summary["native_warning_preferences_restored"] = False
                if log.summary["status"] not in ("FAILED_RESTORE_REQUIRES_ATTENTION",):
                    log.summary["status"] = "FAILED_UI_PREF_RESTORE_REQUIRES_ATTENTION"
        log.summary["finished"] = timestamp()
        log.summary["runtime_seconds"] = time.monotonic()-log.started
        log.summary["real_visum_execution"] = "USER_MACHINE_ONLY; local package tests are mocks"
        if have_lock:
            try:
                lock.unlink()
            except Exception as exc:
                log.warnings.append("Lock cleanup: " + repr(exc))
        log.summary["expected_evidence_zip"] = str(root.parent / (root.name + "_EVIDENCE.zip"))
        log.event("END", log.summary["status"])
        try:
            zip_path = evidence_zip(root)
            # Evidence ZIP path is deterministic, next to RUN_*; never print.
        except Exception as exc:
            log.warnings.append("Evidence ZIP failed: " + repr(exc))
            write_json(root / "00_MASTER_SUMMARY.json", log.summary)
    return log.summary


def run_no_popup():
    # PTV Visum's embedded Python console converts print/sys.stdout writes
    # into MODAL INFORMATION DIALOGS. Capture incidental library output too.
    # Normal progress and failures remain in 00_STATUS / 00_MASTER_SUMMARY.
    try:
        import contextlib
        import tempfile
        with tempfile.TemporaryFile(mode="w+", encoding="utf-8") as suppressed_output:
            with contextlib.redirect_stdout(suppressed_output), contextlib.redirect_stderr(suppressed_output):
                return main()
    except BaseException:
        # Failures before RUN_* initialization cannot be logged there.
        # Keep their traceback on disk, but NEVER call print or show a dialog.
        try:
            import tempfile
            p = Path(tempfile.gettempdir()) / (SCRIPT_ID + "_EARLY_ERROR.txt")
            p.write_text(timestamp() + "\n" + traceback.format_exc(), encoding="utf-8")
        except Exception:
            pass
        return None


if __name__ == "__main__":
    run_no_popup()
